# SPDX-License-Identifier: BSD-2-Clause-Patent
"""iPhone-specific Legacy ABI; header generator derived from UniXNU-sheng.

Reference: 6c42e1055ffb3b335fda991190ad221edaa7af3c/scripts/build-gop-legacy-display-27.py.
Only reviewed iPhone addresses are accepted. No hardware parameters are inherited.
"""
import hashlib,json,struct,sys
from pathlib import Path

def require(ok, message):
    if not ok: raise ValueError(message)

def discriminator(name):
    """clang ptrauth_string_discriminator: SipHash-2-4 with the fixed key, modulo 0xffff, plus one."""
    mask = (1 << 64) - 1
    rotl = lambda x, b: ((x << b) | (x >> (64 - b))) & mask  # noqa: E731
    key = bytes([0xb5, 0xd4, 0xc9, 0xeb, 0x79, 0x10, 0x4a, 0x79, 0x6f, 0xec, 0x8b, 0x1b, 0x42, 0x87, 0x81, 0xd4])
    k0, k1 = struct.unpack('<2Q', key)
    v = [0x736f6d6570736575 ^ k0, 0x646f72616e646f6d ^ k1, 0x6c7967656e657261 ^ k0, 0x7465646279746573 ^ k1]

    def rounds(n):
        for _ in range(n):
            v[0] = (v[0] + v[1]) & mask; v[1] = rotl(v[1], 13) ^ v[0]; v[0] = rotl(v[0], 32)
            v[2] = (v[2] + v[3]) & mask; v[3] = rotl(v[3], 16) ^ v[2]
            v[0] = (v[0] + v[3]) & mask; v[3] = rotl(v[3], 21) ^ v[0]
            v[2] = (v[2] + v[1]) & mask; v[1] = rotl(v[1], 17) ^ v[2]; v[2] = rotl(v[2], 32)
    data = name.encode()
    full = len(data) & ~7
    for i in range(0, full, 8):
        m = struct.unpack_from('<Q', data, i)[0]
        v[3] ^= m; rounds(2); v[0] ^= m
    b = len(data) << 56 & mask
    for i, c in enumerate(data[full:]):
        b |= c << (8 * i)
    v[3] ^= b; rounds(2); v[0] ^= b; v[2] ^= 0xff; rounds(4)
    return (v[0] ^ v[1] ^ v[2] ^ v[3]) % 0xffff + 1


def generate_header(abi):
    BASE=abi['base_slots']; MACOS=False
    ABI_PATH=Path('legacy-display-24A446-iphone12-1.json')
    slots=[(int(t,16),int(d,16)) for t,d in abi['slots']]
    D,R,N=abi['display'],abi['request'],{}
    PROTOTYPES = {
        'isMainDisplay': 'bool isMainDisplay()', 'getDotPitch': 'IOReturn getDotPitch(uint32_t *)',
        'supportedFrameInfo': 'IOReturn supportedFrameInfo(uint32_t,uint32_t *,char *,uint32_t *)=0',
        'getDisplayDimensions': 'void getDisplayDimensions(uint32_t *,uint32_t *)', 'startHardware': 'bool startHardware()',
        'kickSwapQueue': 'void kickSwapQueue()', 'completeCurrentSwap': 'void completeCurrentSwap()',
        'validateSwap': 'bool validateSwap(const OriginalLegacySwapRequest *)',
        'getRefreshAttributes': 'bool getRefreshAttributes(uint64_t *,bool)',
        'collectCompletionReports': 'IOReturn collectCompletionReports(uint32_t,void *,uint32_t *,uint32_t)=0',
        'applyStateRequest': 'int applyStateRequest(OriginalLegacyStateRequest *,bool)',
        # Slot 366: swap_wait_gated calls it (this only, result logged) after a swap waited 5 s, then cancels its own queue (slot 367).
        'cancelSwapsAfterTimeout': 'bool cancelSwapsAfterTimeout()',
        # Slot 316 initializes optional family state and returns void; x0 is not an IOSurface result.
        'create_default_fb_surface': 'void create_default_fb_surface()'}
    # A macOS fixture carries its own prototypes (the reference labels plus the family hooks it implements).
    PROTOTYPES = abi.get('prototypes', PROTOTYPES)
    by_slot = {slot: name for name, slot in abi['methods'].items()}
    PURE_TARGET = int(abi['pure_target'], 16) if 'pure_target' in abi else slots[214][0]
    pure = {i for i, (t, _) in enumerate(slots) if t == PURE_TARGET}
    renames = []
    for base, (name, suffix) in abi['names'].items():
        mangled = f'_ZN25IOMobileFramebufferLegacy{len(name)}{name}{suffix}'
        slot = abi['methods'].get(base) or int(base[len('opaque'):])
        require(discriminator(mangled) == slots[slot][1], f'Reviewed name {name} has the diversity of slot {slot}')
        renames.append(f'#define {base} {name}\n')
    leaves = ' '.join(f'LEAF({i})' for i in abi['leaves'])
    # The macOS family's swap request and notification fields (gen-board-abi.py); the iPadOS header has none of them.
    MACOS_CONSTANTS = ('#define NATIVE_LEGACY_MACOS 1\n'
        f"static constexpr unsigned kLegacyCurrentSwap={D['current']};\n"
        f"static constexpr unsigned kRequestDropReasons={R.get('drop_reasons', 0)},kRequestSwapInfoA={R.get('swap_info_a', 0)},kRequestSwapInfoB={R.get('swap_info_b', 0)};\n"
        f"static constexpr unsigned kLegacySwapInfoTime={D.get('swap_info_time', 0)},kLegacySwapInfoHeld={D.get('swap_info_held', 0)};\n"
        f"static constexpr unsigned kNotifyAsyncReference={N.get('async_reference', 0)},kNotifyMask={N.get('mask', 0)},kNotifyLastTime={N.get('last_time', 0)};\n"
        ) if MACOS else ''
    header = f'''// SPDX-License-Identifier: BSD-2-Clause-Patent
    // Opaque ABI storage for the original iPadOS 27 (24A446) class, generated from {ABI_PATH.name}. Each original slot is declared
    // under a name whose pointer-authentication discriminator is the original slot's diversity (the names below), so original
    // callers authenticate the owned subclass's entries. Only qualified base prototypes may be called from source.
    #pragma once
    #include <IOKit/IOService.h>
    #include <libkern/libkern.h>
    extern "C" OSObject *native_legacy_default_surface_create(OSObject *,uint32_t,uint32_t);
    struct OriginalLegacySwapRequest;
    struct OriginalLegacyStateRequest {{uint32_t skipRequested,requested,skipPowered,powered;uint8_t changed;uint8_t pad[11];}};
    static constexpr unsigned kLegacyVsyncClients={D['vsync_clients']};
    static constexpr unsigned kRequestRect0={R['rect0']},kRequestRect1={R['rect1']},kRequestMasks={R['masks']},kRequestOptions={R['options']},kRequestDims={R['dims']},kRequestSurfaces={R['surfaces']};
    #define NATIVE_LEGACY_LEAVES(LEAF) {leaves}
    #define NATIVE_LEGACY_DEFAULT_SURFACE 1
    #define NATIVE_LEGACY_CANCEL_SWAPS 1
    {MACOS_CONSTANTS}static constexpr unsigned kLegacyDefaultSurface={D['default_surface']};
    {''.join(renames)}class IOMobileFramebufferLegacy : public IOService {{
     OSDeclareAbstractStructors(IOMobileFramebufferLegacy)
     unsigned char originalPrivate[{abi['instance_size']}-sizeof(IOService)];
    public:
     bool installDefaultSurface(uint32_t width,uint32_t height) {{
      auto self=reinterpret_cast<unsigned char *>(this);
      OSObject *root=nullptr,*surface=nullptr;
      memcpy(&surface,self+kLegacyDefaultSurface,sizeof(surface));
      if(surface)return true;
      memcpy(&root,self+{D['surface_root']},sizeof(root));
      if(!root)return false;
      surface=native_legacy_default_surface_create(root,width,height);
      if(!surface)return false;
      // Transfer the factory reference to the family; its stop path releases this field.
      memcpy(self+kLegacyDefaultSurface,&surface,sizeof(surface));
      return true;
     }}
     void installBootDimensions(uint32_t width,uint32_t height) {{
      memcpy(reinterpret_cast<unsigned char *>(this)+{D['width']},&width,4);memcpy(reinterpret_cast<unsigned char *>(this)+{D['height']},&height,4);
     }}
     const OriginalLegacySwapRequest *pendingSwapRequest() const {{
      const OriginalLegacySwapRequest *request=nullptr;
      memcpy(&request,reinterpret_cast<const unsigned char *>(this)+{D['head']},sizeof(request));return request;
     }}
     // Tail queue: head {D['head']}, tail pointer {D['tail']}, each request's next {R['next']} and previous-link {R['prev']}; the head moves
     // to the current-swap slot {D['current']} for the original completion body.
     bool activateOnlyPendingSwap(const OriginalLegacySwapRequest *request) {{
      auto self=reinterpret_cast<unsigned char *>(this);
      auto bytes=reinterpret_cast<const unsigned char *>(request);
      const void *current=nullptr,*head=nullptr,*tail=nullptr,*next=nullptr,*previous=nullptr;
      memcpy(&current,self+{D['current']},8);memcpy(&head,self+{D['head']},8);memcpy(&tail,self+{D['tail']},8);
      if(!request || current || head!=request)return false;
      memcpy(&next,bytes+{R['next']},8);memcpy(&previous,bytes+{R['prev']},8);
      if(previous!=self+{D['head']})return false;
      if(next) {{
       const void *link=self+{D['head']};
       memcpy(const_cast<unsigned char *>(reinterpret_cast<const unsigned char *>(next))+{R['prev']},&link,8);
      }} else if(tail!=bytes+{R['next']})return false;
      memcpy(self+{D['current']},&request,8);
      if(next) {{memcpy(self+{D['head']},&next,8);}}
      else {{const void *empty=nullptr,*emptyTail=self+{D['head']};memcpy(self+{D['head']},&empty,8);memcpy(self+{D['tail']},&emptyTail,8);}}
      return true;
     }}
     void free() override;
     bool init(OSDictionary *properties=nullptr) override;
     IOReturn setProperties(OSObject *) override;
     void systemWillShutdown(IOOptionBits) override;
     IOService *probe(IOService *,SInt32 *) override;
     bool start(IOService *) override;
     void stop(IOService *) override;
     IOWorkLoop *getWorkLoop() const override;
     IOReturn newUserClient(task_t,void *,UInt32,IOUserClient **) override;
     IOReturn setPowerState(unsigned long,IOService *) override;
    '''
    for i in range(BASE, len(slots)):
        if i in by_slot:
            header += f' virtual {PROTOTYPES[by_slot[i]]};\n'
        elif i in pure:
            header += f' virtual __attribute__((noreturn)) void opaque{i}()=0;\n'
        else:
            header += f' virtual __attribute__((deprecated("Unclassified ABI: never call from source"))) void opaque{i}();\n'
    header += f'}};\nstatic_assert(sizeof(IOMobileFramebufferLegacy)=={abi["instance_size"]},"Actual original instance extent");\n'
    return header


def audit_donor(donor, abi, tool):
    sys.path.insert(0,str(tool))
    from kc_image import Image, scan
    raw=Path(donor).read_bytes()
    require(hashlib.sha256(raw).hexdigest()==abi['kernelcache_sha256'], 'Wrong iPhone display donor')
    cache=Image(raw);family=Image(raw,cache.entries[abi['family']][1]);fix=cache.fixups()
    table=int(abi['vtable'],16);count=len(abi['slots'])
    require(count==379 and abi['base_slots']==168 and int(abi['collection_slide'],16)==0,
            'Unreviewed display ABI shape or slide')
    require(cache.read(table-16,16)==bytes(16) and table+count*8 not in fix,'Display vtable extent changed')
    for i,row in enumerate(abi['raw_slots']):
        require(fix.get(table+8*i)==tuple(row),f'Original display slot {i} changed')
        require(row[0]==int(abi['slots'][i][0],16),'Inconsistent display target')
        if i not in (214,216,257):
            require(row[1:]==[1,0,int(abi['slots'][i][1],16),1],f'Display PAC slot {i} changed')
        else:
            require(row[0]==int(abi['pure_target'],16),'Abstract slot changed')
    for name,entry in abi['anchors'].items():
        address=int(entry['address'],16);f=Image(raw,cache.entries[entry['family']][1])
        require(abi['bindings'][name]==entry['address'],'Display binding differs from checked function')
        require(address in f.function_starts(),f'Display {name} is not a function start')
        require(hashlib.sha256(f.read(address,entry['size'])).hexdigest()==entry['sha256'],f'Changed display {name}')
    for va,expected in abi['checks']:
        require(cache.read(int(va,16),len(bytes.fromhex(expected))).hex()==expected,'Display field/accessor changed')
    getter=fix[table+7*8][0]
    _,refs,_=scan(cache.read(getter,16),getter)
    require(int(abi['bindings']['__ZN25IOMobileFramebufferLegacy10gMetaClassE'],16)
            in [target for _,target,kind in refs if kind=='add'],'Wrong Legacy metaclass')
    registration=abi['metaclass_registration'];va=int(registration['address'],16)
    code=cache.read(va,registration['size'])
    require(va in family.function_starts() and hashlib.sha256(code).hexdigest()==registration['sha256'],
            'Changed Legacy metaclass registration')
    _,refs,_=scan(code,va)
    require(any(family.cstring(target)=='IOMobileFramebufferLegacy' for _,target,kind in refs if kind=='add') and
        int(abi['bindings']['__ZN25IOMobileFramebufferLegacy10gMetaClassE'],16) in
        [target for _,target,kind in refs if kind=='add'],'Legacy class name/registration object changed')
    size=int(abi['instance_size'],16)
    require(0<size<65536 and struct.pack('<I',0x52800003|size<<5) in code,'Legacy instance size differs from original constructor')
    return cache


def object_slots(data):
    """Inspect exact object vtable authentication relocations, not nm text."""
    from build_ufs_dormant import macho
    info=macho(data,1);table=info['defined']['__ZTV19NativeLegacyDisplay']
    commands=[];at=32
    for _ in range(struct.unpack_from('<I',data,16)[0]):
        cmd,size=struct.unpack_from('<II',data,at);commands.append((cmd,at));at+=size
    so,count,st,ss=struct.unpack_from('<4I',data,next(at for cmd,at in commands if cmd==2)+8)
    symbols=[]
    for i in range(count):
        ix=struct.unpack_from('<I',data,so+16*i)[0]
        require(ix<ss,'Object symbol out of bounds')
        stop=data.find(b'\0',st+ix,st+ss);require(stop>=0,'Unterminated object symbol')
        symbols.append(data[st+ix:stop].decode())
    rows={}
    for cmd,at in commands:
        if cmd!=25:continue
        for index in range(struct.unpack_from('<I',data,at+64)[0]):
            pos=at+72+index*80
            va,size,off,align,ro,rc=struct.unpack_from('<QQ4I',data,pos+32)
            require(ro+rc*8<=len(data),'Display relocation table truncated')
            for j in range(rc):
                addr,bits=struct.unpack_from('<iI',data,ro+j*8);site=va+addr
                if not table+16<=site<=table+16+379*8:continue
                require(site not in rows and addr>=0 and addr+8<=size and off+addr+8<=len(data),'Bad display relocation')
                require(bits>>28==11 and bits>>27&1 and bits>>25&3==3 and not bits>>24&1,'Display slot is not authenticated')
                require(bits&0xffffff<len(symbols),'Bad display relocation symbol')
                word=struct.unpack_from('<Q',data,off+addr)[0]
                require(word>>63 and word&0xffffffff==0 and word>>51&0xfff==0,'Bad display relocation addend')
                rows[site]=dict(name=symbols[bits&0xffffff],auth=1,key=word>>49&3,
                    diversity=word>>32&0xffff,address_diversity=word>>48&1)
    require(table+16+379*8 not in rows and all(table+16+8*i in rows for i in range(379)),
            'Compiled display vtable is not exactly 379 slots')
    return info,[dict(slot=i,**rows[table+16+i*8]) for i in range(379)]


def audit_object(obj,abi,donor=None,native=None,mapping_path=None,tool=None):
    """Require source ABI and, at link time, actual donor/native identities."""
    info,rows=object_slots(Path(obj).read_bytes())
    bindings={name:dict(address=addr,kind='data' if name in
        ('__ZTV25IOMobileFramebufferLegacy','__ZN25IOMobileFramebufferLegacy10gMetaClassE') else 'function')
        for name,addr in abi['bindings'].items()}
    identities={}
    if donor is not None:
        cache=audit_donor(donor,abi,tool)
        from kc_image import Image
        kernel=Image(Path(native).read_bytes());mapping=json.loads(Path(mapping_path).read_text())
        require(cache.base==kernel.base,'Display requires zero-slide original identities')
        require(mapping['inputs']['kernelcache_sha256']==abi['kernelcache_sha256'] and
            mapping['inputs']['native_sha256']==hashlib.sha256(kernel.data).hexdigest(),'Stale display identity map')
        symbols=kernel.symbols()
        for kind in ('functions','data'):
            identities.update({int(k,16):symbols.get(int(v['native'],16),[]) for k,v in mapping[kind].items()})
    owned=[]
    for row,(address,diversity) in zip(rows,abi['slots']):
        i=row['slot'];name=row['name'];addr=int(address,16)
        require((row['auth'],row['key'],row['diversity'],row['address_diversity'])==(1,0,int(diversity,16),1),
                f'Compiled display PAC mismatch at {i}: {name}')
        if name.startswith(('__ZN19NativeLegacyDisplay','__ZNK19NativeLegacyDisplay')):owned.append(i)
        elif '25IOMobileFramebufferLegacy' in name:
            require(addr!=int(abi['pure_target'],16),'Unimplemented display abstract entry')
            if name in bindings:require(bindings[name]['address']==address,'Inconsistent display import')
            bindings[name]=dict(address=address,kind='function')
        else:
            require(i<abi['base_slots'],'Unknown non-base display slot')
            if donor is not None:require(name in identities.get(addr,[]),f'Display inherited slot {i}: {name}')
    require({214,216,257}<=set(owned),'Display pure methods must be implemented')
    undefined={n for n in info['undefined'] if '25IOMobileFramebufferLegacy' in n}
    require(undefined<=set(bindings),'Unbound display base import')
    data_imports=[name for name,row in bindings.items() if row['kind']=='data' and name in info['undefined']]
    require('__ZN25IOMobileFramebufferLegacy10gMetaClassE' in data_imports,'Original display metaclass is not imported')
    return dict(bindings=bindings,methods=rows,vtable_symbol='__ZTV19NativeLegacyDisplay',
        donor_sha256=abi['kernelcache_sha256'],owned_slots=owned,data_imports=data_imports,runtime_qualified=False)

