static bool geometry(const PE_Video &v) {
    return v.v_baseAddr && v.v_display==1 && v.v_depth==32 && !v.v_rotate &&
        v.v_width && v.v_height && v.v_width<=16384 && v.v_height<=16384 &&
        v.v_rowBytes>=v.v_width*4 && v.v_rowBytes<=UINT64_MAX/v.v_height;
}
static void stage(uint32_t value, int32_t status) {
    myron_display_stage=value;myron_display_status=status;
    IOLog("myron-display: stage %u status 0x%x registered %u\n",value,(unsigned)status,myron_display_registered);
}
extern "C" size_t myron_display_snapshot(char *out,size_t cap) {
    if(!out || !cap)return 0;
    int n=snprintf(out,cap,"[myron display]\nstage=%u status=0x%x registered=%u clients=%u client_status=0x%x\n"
        "accepted=%u rejected=%u reject_reason=%u copies=%u copied_bytes=%llu retired=%u\n",
        myron_display_stage,(unsigned)myron_display_status,myron_display_registered,myron_display_clients,
        (unsigned)myron_display_client_status,myron_display_validated,myron_display_rejected,myron_display_reason,
        myron_display_copies,(unsigned long long)myron_display_copy_bytes,myron_display_retired);
    return n<0?0:((size_t)n<cap?(size_t)n:cap-1);
}

// Functional hand-off: never acknowledge while the boot console still writes.
extern "C" bool native_legacy_prepare_scanout(void) {
    if(ml_at_interrupt_context() || !ml_get_interrupts_enabled())return false;
    for(unsigned attempt=0;attempt<32;++attempt) {
        if(myron_boot_progress_prepare_scanout())return true;
        IOSleep(1);
    }
    myron_boot_progress_cancel_scanout();return false;
}
extern "C" bool native_legacy_gop_mapping_observed(IOService *,IOMemoryMap *map,uint32_t w,uint32_t h) {
    bool ok=map && geometry(handoff) && map->getVirtualAddress() &&
        map->getPhysicalAddress()==handoff.v_baseAddr && map->getLength()==handoff.v_rowBytes*handoff.v_height &&
        w==handoff.v_width && h==handoff.v_height;
    stage(ok?6:16,ok?0:kIOReturnBadArgument);return ok;
}
