extern "C" void myron_display_start(void) {
    unsigned enable=0;PE_parse_boot_argn("myron27-display",&enable,sizeof enable);
    if(enable!=1 || !__sync_bool_compare_and_swap(&claimed,0U,1U))return;
    stage(1,0);
    // This board owns only the firmware's existing scanout. Unsupported optional
    // paths must not become active by accidentally reusing another board's args.
    const char *unsupported[]={"fb-gpu","dpu-scanout","offline-legacy-pm","vsync"};
    for(const char *name:unsupported) {
        unsigned option=0;PE_parse_boot_argn(name,&option,sizeof option);
        if(option){stage(17,kIOReturnUnsupported);return;}
    }
    unsigned phase=0;PE_parse_boot_argn("offline-legacy-phase",&phase,sizeof phase);
    if(phase!=4 || PE_current_console(&handoff) || !geometry(handoff)){stage(18,kIOReturnBadArgument);return;}
    IOLog("myron-display: actual GOP %ux%u stride %u depth %u\n",(unsigned)handoff.v_width,
        (unsigned)handoff.v_height,(unsigned)handoff.v_rowBytes,(unsigned)handoff.v_depth);
    kern_return_t status=OSKextLoadKextWithIdentifier("com.apple.iokit.IOMobileGraphicsFamily");
    if(status){stage(19,status);return;}
    status=OSKextLoadKextWithIdentifier("com.apple.iokit.IOSurface");
    if(status){stage(20,status);return;}
    OSDictionary *match=OSDictionary::withCapacity(1);
    const OSObject *names[]={OSString::withCString("IOCoreSurfaceRoot"),OSString::withCString("IOSurfaceRoot")};
    OSArray *list=names[0] && names[1]?OSArray::withObjects(names,2):nullptr;
    if(!match || !list || !match->setObject(gIONameMatchKey,list))OSSafeReleaseNULL(match);
    OSSafeReleaseNULL(list);for(const OSObject *name:names)if(name)name->release();
    IOService *surface=match?IOService::waitForMatchingService(match,5000000000ULL):nullptr;
    OSSafeReleaseNULL(match);
    if(!surface){stage(21,kIOReturnNotFound);return;}surface->release();
    stage(2,0);
    void *handle=OSMetaClass::preModLoad(g_kernel_kmod_info.name);
    if(!handle){stage(22,kIOReturnNoMemory);return;}
    native_legacy_display_static_init();
    status=OSMetaClass::postModLoad(handle);
    if(status){stage(23,status);return;}
    IOService *display=native_legacy_display_allocate();
    if(!display || !display->metaCast("IOMobileFramebufferLegacy") || !display->init()) {
        OSSafeReleaseNULL(display);stage(24,kIOReturnError);return;
    }
    stage(3,0);
    IOService *nub=new IOService,*parent=IOService::getResourceService();
    IORegistryEntry *dt=IORegistryEntry::fromPath("/arm-io",gIODTPlane);
    IODeviceMemory *memory=IODeviceMemory::withRange(handoff.v_baseAddr,handoff.v_rowBytes*handoff.v_height);
    OSArray *ranges=OSArray::withCapacity(1);
    bool nubAttached=false,nubStarted=false,dtAttached=false,attached=false,started=false;
    if(nub && parent && dt && memory && ranges && nub->init() && ranges->setObject(memory)) {
        nub->setDeviceMemory(ranges);nub->setName("MyronGOPFramebuffer");
        nubAttached=nub->attach(parent);if(nubAttached)nubStarted=nub->start(parent);
        const char type[]="display-subsystem";OSData *data=OSData::withBytes(type,sizeof type);
        if(nubStarted && data && nub->setProperty("device_type",data)) {
            nub->setName("gop-display",gIODTPlane);dtAttached=nub->attachToParent(dt,gIODTPlane);
        }
        OSSafeReleaseNULL(data);
        SInt32 score=0;
        if(dtAttached && display->probe(nub,&score)==display)attached=display->attach(nub);
        if(attached){stage(4,0);started=display->start(nub);}
    }
    if(started && myron_display_registered) {
        activeDisplay=display;activeNub=nub;stage(10,0);
        boot_progress_stage("myron GOP display registered; awaiting real frame");
        OSSafeReleaseNULL(ranges);OSSafeReleaseNULL(memory);OSSafeReleaseNULL(dt);return;
    }
    if(started)display->stop(nub);if(attached)display->detach(nub);
    myron_display_registered=0;
    if(dtAttached)nub->detachFromParent(dt,gIODTPlane);
    if(nubStarted)nub->stop(parent);if(nubAttached)nub->detach(parent);
    OSSafeReleaseNULL(ranges);OSSafeReleaseNULL(memory);OSSafeReleaseNULL(dt);
    OSSafeReleaseNULL(nub);OSSafeReleaseNULL(display);stage(25,kIOReturnNotReady);
}

