        calls = [[1, 6], [2, 3, 4, 5, 18], [], [], [], [], [], [8], [], [1], [11, 19, 21], [12, 13, 14, 15], [], [], [], [16, 16, 17], [], [], [], [20, 13], [], [20, 22], []]
        offsets, cursor = [], 0
        for targets in calls:
            offsets.append(cursor); cursor += 4 * (len(targets) + 1)
        code = bytearray()
        for i, targets in enumerate(calls):
            for target in targets:
                relative = (offsets[target] - len(code)) // 4
                code.extend(struct.pack('<I', 0x94000000 | (relative & 0x3ffffff)))
            code.extend(struct.pack('<I', 0xd65f03c0))
        strings, symbols = b'\0', b''
        base, text = 0x1000, 224
        for name, offset in zip(names, offsets):
            symbols += struct.pack('<IBBHQ', len(strings), 0xf, 1, 0, base + text + offset)
            strings += name.encode() + b'\0'
        starts = bytes([0xe0, 1, *[b-a for a, b in zip(offsets, offsets[1:])], 0])
        symoff = text + len(code); stroff = symoff + len(symbols)
