        header = struct.pack('<8I', 0xfeedfacf, 0x100000c, 2, 2, 3, 192, 0, 0)
        segment = struct.pack('<II16s4Q4I', 0x19, 152, b'__TEXT', base, extent, 0, extent, 7, 5, 1, 0)
        section = struct.pack('<16s16sQQ8I', b'__text', b'__TEXT', base+text, len(code), text, 2, 0, 0, 0x80000400, 0, 0, 0)
        symtab = struct.pack('<6I', 2, 24, symoff, len(names), stroff, len(strings))
