// SPDX-License-Identifier: MIT
// Adapted from UniXNU-sheng's periodic v5 UFS log; no board reset/panic transport.
// Included after MyronRootBoot.h. Root/policy identity has already been checked.
#include "MyronBootLogCore.h"
#include <sys/msgbuf.h>
extern "C" struct msgbuf *msgbufp;
extern "C" size_t myron_boot_log_snapshot(char *,size_t);
#if MYRON_ROOT_POLICY
extern "C" size_t myron_display_snapshot(char *,size_t);
#endif
extern "C" void bsd_log_lock_safe(void);
extern "C" void bsd_log_unlock(void);
extern "C" {
volatile uint32_t myron_log_state, myron_log_rounds, myron_log_errors;
volatile uint64_t myron_log_first_lba;
}
static uint64_t myronLogFirst;
static unsigned myronLogStarted;
static int myronLogWrite(uint64_t rel,uint32_t n,const void *src) {
 if(!myronLogFirst || !src || !myronLogRange(rel,n)) return 0;
 while(n) {
  uint32_t chunk=n>kDataMax/4096 ? (uint32_t)(kDataMax/4096) : n;
  if(hostWrite4k(0,myronLogFirst+rel,chunk,src)!=kIOReturnSuccess) return 0;
  rel+=chunk;n-=chunk;src=(const uint8_t *)src+chunk*4096ULL;
 }
 return 1;
}
static uint32_t myronLogMessages(uint8_t *out) {
 memset(out,0,MyLogMsgBlocks*MyLogBlock);
 // Protect the source pointer against kern.msgbuf resizing/freeing. The lock
 // covers only two bounded memory copies; no allocation, formatting or I/O.
 bsd_log_lock_safe();
 struct msgbuf *m=msgbufp; uint32_t copied=0;
 if(m && m->msg_bufc && m->msg_magic==MSG_MAGIC && m->msg_size>0 && m->msg_size<=MAX_MSG_BSIZE &&
    m->msg_bufx>=0 && m->msg_bufx<m->msg_size) {
  const unsigned size=(unsigned)m->msg_size,x=(unsigned)m->msg_bufx;
  copied=size>MyLogMsgBlocks*MyLogBlock ? MyLogMsgBlocks*MyLogBlock : size;
  const unsigned begin=(x+size-copied)%size;
  const unsigned part=copied<size-begin ? copied : size-begin;
  memcpy(out,m->msg_bufc+begin,part);
  if(part<copied)memcpy(out+part,m->msg_bufc,copied-part);
 }
 bsd_log_unlock();
 uint32_t n=0;
 for(uint32_t i=0;i<copied;++i)if(out[i])out[n++]=out[i];
 memset(out+n,0,MyLogMsgBlocks*MyLogBlock-n);
 return n;
}
static void myronLogWorker(void *,wait_result_t) {
 thread_set_thread_name(current_thread(),"myron_boot_log");
 uint64_t first=0;
 // Both legacy write APIs stay closed; the board opens only this 512 KiB window.
 if(!myron_root_start_ready || !gStoreGeometry.valid || !gHost.ready || gHost.poisoned ||
    storeMode() || logMode() || gStoreOpen || gLogOpen ||
    reserveBlocks()!=myron_root_geometry.reserveBlocks ||
    !myronLogWindow(myron_root_geometry,gStoreGeometry.imageBytes,gStoreGeometry.first,gStoreGeometry.last,&first) ||
    native_ufs_store_gpt_check()!=0) {myron_log_state=3;return;}
 const size_t bytes=(2*MyLogMsgBlocks+MyLogSlotBlocks+1)*MyLogBlock;
 uint8_t *allocation=(uint8_t *)IOMallocAligned(bytes,MyLogBlock);
 if(!allocation) {myron_log_state=3;return;}
 if(!hostLogOpen(first,MyLogBlocks)) {IOFreeAligned(allocation,bytes);myron_log_state=3;return;}
 myronLogFirst=first;myron_log_first_lba=first;
 uint8_t *msg=allocation,*previous=msg+MyLogMsgBlocks*MyLogBlock;
 uint8_t *slot=previous+MyLogMsgBlocks*MyLogBlock,*header=slot+MyLogSlotBlocks*MyLogBlock;
 memset(allocation,0,bytes);
 MyronLogHeader h={}; MyronLogCheck checks={};
 memcpy(h.magic,"SHLOG001",8);h.version=5;h.header_bytes=sizeof h;
 h.boot_id=timerTicks();h.first_lba=first;h.window_blocks=MyLogBlocks;
 h.msg_first=MyLogMsgFirst;h.msg_blocks=MyLogMsgBlocks;
 h.slot_first=MyLogSlotFirst;h.slot_blocks=MyLogSlotBlocks;h.slot_count=MyLogSlotCount;
 strlcpy(h.tag,"myron-persist-v1",sizeof h.tag);memcpy(checks.magic,"MYLGC001",8);
 uint64_t hz=0;__asm__ volatile("mrs %0, cntfrq_el0":"=r"(hz));
 if(!hz)hz=19200000;
 const uint64_t start=timerTicks();bool previousValid=false;
 myron_log_state=2;
 for(;;) {
  // A changed GPT or poisoned transport stops writes permanently for this boot.
  if(!gHost.ready || gHost.poisoned) {myron_log_state=3;break;}
  if(!(h.rounds%30) && native_ufs_store_gpt_check()!=0) {myron_log_state=4;break;}
  h.uptime_s=(uint32_t)((timerTicks()-start)/hz);h.state=2;
  h.msg_bytes=myronLogMessages(msg);
  memset(slot,0,MyLogSlotBlocks*MyLogBlock);
  int prefix=snprintf((char *)slot,MyLogBlock,"[myron] boot=%llx round=%u log_seconds=%u\n",
      (unsigned long long)h.boot_id,h.rounds+1,h.uptime_s);
  if(prefix<0 || prefix>=MyLogBlock) {myron_log_state=3;break;}
#if MYRON_ROOT_POLICY
  // Keep display status even when the general evidence fills the slot.
  const size_t displayRemaining=MyLogSlotBlocks*MyLogBlock-(size_t)prefix;
  prefix+=(int)myron_display_snapshot((char *)slot+prefix,displayRemaining<512?displayRemaining:512);
#endif
  size_t n=myron_boot_log_snapshot((char *)slot+prefix,MyLogSlotBlocks*MyLogBlock-(size_t)prefix);
  uint32_t used=(uint32_t)prefix+(uint32_t)n+1;
  if(!myronLogCommit(h,checks,msg,previous,previousValid,slot,used,header,
        [](uint64_t rel,uint32_t count,const void *data){return myronLogWrite(rel,count,data)!=0;},
        [](){return hostSyncCache()==kIOReturnSuccess;})) {
   ++myron_log_errors;myron_log_state=3;break;
  }
  memcpy(previous,msg,MyLogMsgBlocks*MyLogBlock);previousValid=true;myron_log_rounds=h.rounds;
  IOSleep(2000);
 }
 // hostLogOpen remains bounded and reserved. No further writes/retry on failure.
 IOFreeAligned(allocation,bytes);
}
static void myronBootLogStart(void) {
 unsigned on=0;PE_parse_boot_argn("log",&on,sizeof on);
 if(on!=1 || !__sync_bool_compare_and_swap(&myronLogStarted,0U,1U)) return;
 myron_log_state=1;thread_t thread=THREAD_NULL;
 if(kernel_thread_start(myronLogWorker,nullptr,&thread)==KERN_SUCCESS)thread_deallocate(thread);
 else myron_log_state=3;
}
